// Taxonic Developer Toolkit v1.1
// 1. Plak hieronder de volledige actuele Copy as cURL.
// 2. Voer Toolkit - Handmatig starten uit.
// 3. De gevonden sessiewaarden worden automatisch opgeslagen.
// 4. Start daarna de normale vacatureworkflow; handmatig kopiëren is niet nodig.

const curl = String.raw`
PLAK_HIER_DE_VOLLEDIGE_CURL
`.trim();

const jsonResponse = String.raw`
PLAK_HIER_EVENTUEEL_DE_JSON_RESPONSE
`.trim();

return [{
  json: {
    toolkitVersie: '1.1',
    curl,
    jsonResponse
  }
}];

// Taxonic Developer Toolkit v1.0
const input=$input.first()?.json||{};
const original=String(input.curl||'').trim();
if(!original||original==='PLAK_HIER_DE_VOLLEDIGE_CURL') throw new Error('Plak eerst een volledige cURL in Toolkit - Invoer cURL en JSON.');
const curl=original.replace(/\r/g,'').replace(/\^\n/g,' ').replace(/\\\n/g,' ').replace(/\n+/g,' ').replace(/\s+/g,' ').replace(/\^%/g,'%').replace(/\^\$/g,'$').replace(/\^&/g,'&').replace(/\^"/g,'"').trim();
const u=curl.match(/curl(?:\.exe)?\s+(?:"([^"]+)"|'([^']+)'|([^\s]+))/i); const url=u?.[1]||u?.[2]||u?.[3]||'';
const m=curl.match(/(?:^|\s)(?:-X|--request)\s+(?:"([^"]+)"|'([^']+)'|([A-Z]+))/i);
const bodies=[...curl.matchAll(/(?:^|\s)(?:--data-raw|--data-binary|--data|-d)\s+(?:"((?:[^"\\]|\\.)*)"|'([^']*)')/gi)];
const body=bodies.length?(bodies.at(-1)[1]??bodies.at(-1)[2]??''):''; const method=String(m?.[1]||m?.[2]||m?.[3]||(body?'POST':'GET')).toUpperCase();
const headers={}; for(const x of curl.matchAll(/(?:^|\s)(?:-H|--header)\s+(?:"((?:[^"\\]|\\.)*)"|'([^']*)')/gi)){const raw=(x[1]??x[2]??'').replace(/\\"/g,'"'); const i=raw.indexOf(':'); if(i>0) headers[raw.slice(0,i).trim()]=raw.slice(i+1).trim();}
const cookies={}; const ck=Object.keys(headers).find(k=>k.toLowerCase()==='cookie'); if(ck){for(const p of headers[ck].split(';')){const i=p.indexOf('='); if(i>0) cookies[p.slice(0,i).trim()]=p.slice(i+1).trim();}}
const ah=Object.keys(headers).find(k=>k.toLowerCase()==='authorization'); const authorization=ah?headers[ah]:''; const bearerToken=authorization.replace(/^Bearer\s+/i,'').trim();
const queryParameters={}; try{const pu=new URL(url); for(const [k,v] of pu.searchParams.entries()) queryParameters[k]=queryParameters[k]===undefined?v:[].concat(queryParameters[k],v);}catch(e){}
let bodyJson=null; for(const candidate of [body,body.replace(/\\"/g,'"')]){try{bodyJson=JSON.parse(candidate);break;}catch(e){}}
const jwtKandidaten=[]; const add=(bron,val)=>{for(const z of String(val||'').matchAll(/eyJ[a-zA-Z0-9_-]+\.[a-zA-Z0-9_-]+\.[a-zA-Z0-9_-]+/g)) if(!jwtKandidaten.some(i=>i.token===z[0])) jwtKandidaten.push({bron,token:z[0]});}; add('authorization',bearerToken); add('body',body); for(const [k,v] of Object.entries(cookies)){let d=v;try{d=decodeURIComponent(v)}catch(e){} add('cookie:'+k,d)}
return [{json:{...input,request:{method,url,headers,queryParameters,bodyRaw:body,bodyJson},cookies,authorization,bearerToken,jwtKandidaten}}];

// Taxonic Developer Toolkit v1.0
const i=$input.first()?.json||{}, c=i.cookies||{}, h=i.request?.headers||{};
const cookie=(...n)=>{for(const x of n){const k=Object.keys(c).find(y=>y.toLowerCase()===x.toLowerCase());if(k)return c[k]}return''};
const header=(...n)=>{for(const x of n){const k=Object.keys(h).find(y=>y.toLowerCase()===x.toLowerCase());if(k)return h[k]}return''};
return [{json:{...i,herkenning:{session:cookie('SESSION','JSESSIONID','PHPSESSID','STRIIVE_SESSION'),xsrfToken:cookie('XSRF-TOKEN','STRIIVE_XSRF_TOKEN')||header('x-xsrf-token','x-csrf-token'),cid:cookie('CID','STRIIVE_CID'),kcSession:cookie('__kc_session'),kcRefresh:cookie('__kc_refresh'),idToken:cookie('freelance_id_token','id_token'),refreshToken:cookie('freelance_refresh_token','refresh_token'),companyId:cookie('freelance_company_id','company_id')||header('x-company-id'),authorization:i.authorization||'',bearerToken:i.bearerToken||'',csrf:header('x-csrf-token'),nonce:header('x-wp-nonce'),apiKey:header('x-api-key','api-key')}}}];

// Taxonic Developer Toolkit v1.0
const i=$input.first()?.json||{},r=i.request||{}; const hp=Object.entries(r.headers||{}).filter(([n])=>n.toLowerCase()!=='content-length').map(([name,value])=>({name,value}));
return [{json:{...i,n8nHttpRequestBlueprint:{method:r.method||'GET',url:r.url||'',sendHeaders:hp.length>0,headerParameters:{parameters:hp},sendBody:Boolean(r.bodyRaw),contentType:r.bodyRaw?'raw':undefined,rawContentType:(r.headers||{})['Content-Type']||(r.headers||{})['content-type']||'application/json',body:r.bodyRaw||undefined,options:{timeout:60000,response:{response:{responseFormat:'json'}}}}}}];

// Taxonic Developer Toolkit v1.0
const i=$input.first()?.json||{}; let raw=String(i.jsonResponse||'').trim(); if(!raw||raw==='PLAK_HIER_EVENTUEEL_DE_JSON_RESPONSE') return [{json:{...i,jsonAnalyse:{status:'geen-json-ingevuld'}}}];
let p=null; for(const x of [raw,raw.replace(/\\"/g,'"')]){try{p=JSON.parse(x);break}catch(e){}} if(!p) throw new Error('De geplakte JSON-response kon niet worden geparsed.');
const rows=[]; const walk=(v,path='$',d=0)=>{if(d>7)return;if(Array.isArray(v)){rows.push({pad:path,type:'array',lengte:v.length});if(v.length)walk(v[0],path+'[0]',d+1);return;}if(v&&typeof v==='object'){rows.push({pad:path,type:'object',keys:Object.keys(v)});for(const[k,x]of Object.entries(v))walk(x,path+'.'+k,d+1);return;}rows.push({pad:path,type:v===null?'null':typeof v,voorbeeld:typeof v==='string'?v.slice(0,120):v});}; walk(p);
const arrays=rows.filter(x=>x.type==='array').sort((a,b)=>b.lengte-a.lengte); const fields={}; const patterns={titel:/(^|\.)(title|titel|name|naam)$/i,omschrijving:/(^|\.)(description|omschrijving|beschrijving|content|text)$/i,id:/(^|\.)(id|key|uuid|opdrachtkey|publicationid|docid)$/i,url:/(^|\.)(url|link|slug|permalink|vacatureurl)$/i,opdrachtgever:/(^|\.)(company|client|opdrachtgever|bedrijfsnaam|organisatie)$/i,locatie:/(^|\.)(location|locatie|city|plaats|province)$/i,tarief:/(^|\.)(rate|tarief|ratefrom|rateto|maxrate)$/i,uren:/(^|\.)(hours|uren|hoursfrom|hoursto|hoursperweek)$/i,deadline:/(^|\.)(deadline|closingdate|sluiting|applicationdeadlinedate|publishuntil)$/i}; for(const[k,re]of Object.entries(patterns))fields[k]=rows.filter(x=>re.test(x.pad)).map(x=>x.pad).slice(0,15);
const paginering={skip:rows.filter(x=>(/(^|\.)skip$/i).test(x.pad)),offset:rows.filter(x=>(/(^|\.)offset$/i).test(x.pad)),page:rows.filter(x=>(/(^|\.)(page|currentpage|pagenumber)$/i).test(x.pad)),cursor:rows.filter(x=>(/(cursor|nexttoken)/i).test(x.pad)),total:rows.filter(x=>(/(^|\.)(count|total|totalcount|tcount|vacancycount)$/i).test(x.pad))};
return [{json:{...i,jsonAnalyse:{status:'ok',topLevelKeys:p&&typeof p==='object'&&!Array.isArray(p)?Object.keys(p):[],waarschijnlijkResultaatArray:arrays.find(x=>/list|results|items|assignments|vacancies|jobs/i.test(x.pad))||arrays[0]||null,arrayKandidaten:arrays.slice(0,15),veldKandidaten:fields,paginering,structuurPreview:rows.slice(0,200)}}}];

// Taxonic Developer Toolkit — deadlineversie
const input = $input.first()?.json || {};
const request = input.request || {};

return [{
  json: {
    toolkitVersie: 'Deadline 2026-08-04',
    request: {
      method: request.method || '',
      url: request.url || '',
      queryParameters: request.queryParameters || {},
      headers: request.headers || {},
      bodyRaw: request.bodyRaw || '',
      bodyJson: request.bodyJson ?? null
    },
    cookies: input.cookies || {},
    herkenning: input.herkenning || {},
    belangrijkeHeaders: input.belangrijkeHeaders || {},
    jwtKandidaten: input.jwtKandidaten || [],
    n8nHttpRequestBlueprint:
      input.n8nHttpRequestBlueprint || {},
    jsonAnalyse: input.jsonAnalyse || {},
    paginering: input.paginationDetector || {},
    waarschuwing:
      'Deze output kan geheime sessiewaarden bevatten. Deel hem niet openbaar.'
  }
}];

// Toolkit opslagbevestiging
const record = $('Toolkit - Eindrapport').first().json || {};

return [{
  json: {
    gelukt: true,
    broker: record.broker || '',
    host: record.host || '',
    status: 'Sessie permanent opgeslagen',
    bijgewerktOp: record.updated_at || '',
    volgendeStap:
      'Start nu de normale vacatureworkflow. Handmatig kopiëren is niet nodig.'
  }
}];
